{
  "name": "inject-user-id",
  "version": "0.3.0",
  "description": "OpenCode plugin that injects metadata.user_id into configured model request URLs for prompt-cache stickiness",
  "license": "MIT",
  "author": "heiyan-2020",
  "type": "module",
  "exports": "./index.ts",
  "main": "./index.ts",
  "scripts": {
    "test": "INJECT_HOST=api.claudecode.net.cn,relay.example.com,https://prefix.example.com/api/v1 INJECT_ID=acct-42 node --experimental-strip-types test.ts"
  },
  "files": [
    "index.ts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "llm",
    "metadata",
    "cache"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/heiyan-2020/inject-user-id.git"
  },
  "homepage": "https://github.com/heiyan-2020/inject-user-id#readme",
  "bugs": {
    "url": "https://github.com/heiyan-2020/inject-user-id/issues"
  },
  "publishConfig": {
    "access": "public"
  }
}
